 "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#fb7185;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">+56 %</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">ataques impulsados por IA</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">sobre todo suplantaciones con deepfakes y malware con IA</div></div>": "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#fb7185;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">+56 %</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">KI-gestützte Angriffe</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">vor allem Identitätsvortäuschung mit Deepfakes und KI-Malware</div></div>",
 "Una cámara": "Eine Kamera",
 "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#a3e635;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">−1,93 M$</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">menos de coste</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">en organizaciones que usan mucho la IA y la automatización en seguridad</div></div>": "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#a3e635;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">−1,93 Mio. $</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">geringere Kosten</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">bei Organisationen mit starkem KI- und Automatisierungseinsatz in der Sicherheit</div></div>",
